#!/usr/bin/env python3
"""Write src/emoji_codes.rs from rich's emoji table (run with rich installed)."""
from pathlib import Path

from rich._emoji_codes import EMOJI


def lit(s):
    return '"' + "".join("\\u{%x}" % ord(c) if ord(c) > 126 or c in '"\\' else c for c in s) + '"'


lines = [
    "//! rich's emoji codes (`rich._emoji_codes.EMOJI`, rich 15.0), generated by",
    "//! `scripts/gen_emoji.py`: `:name:` -> the emoji.",
    "",
    "/// (name, emoji), sorted by name.",
    "pub const EMOJI: &[(&str, &str)] = &[",
]
lines += [f"    ({lit(k)}, {lit(v)})," for k, v in sorted(EMOJI.items())]
lines += [
    "];",
    "",
    "/// The emoji for a code (`EMOJI[name]`).",
    "pub fn get(name: &str) -> Option<&'static str> {",
    "    EMOJI.binary_search_by(|(k, _)| (*k).cmp(name)).ok().map(|i| EMOJI[i].1)",
    "}",
    "",
]
out = Path(__file__).resolve().parent.parent / "src" / "emoji_codes.rs"
out.write_text("\n".join(lines))
print("wrote", out, len(EMOJI), "codes")
